-- Telegram assistant schema. Feature branch only; not applied to production.
CREATE TABLE public.telegram_link_codes (code_hash text PRIMARY KEY CHECK (code_hash ~ '^[0-9a-f]{64}$'), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX telegram_link_codes_user_id_idx ON public.telegram_link_codes(user_id);
CREATE TABLE public.telegram_accounts (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, telegram_user_id bigint NOT NULL UNIQUE, chat_id bigint NOT NULL, username text, first_name text, last_name text, linked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.telegram_pending_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, telegram_user_id bigint NOT NULL, chat_id bigint NOT NULL, source_message_id bigint, proposal jsonb NOT NULL CHECK (jsonb_typeof(proposal) = 'array' AND jsonb_array_length(proposal) BETWEEN 1 AND 5), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','confirmed','rejected','expired')), expires_at timestamptz NOT NULL DEFAULT (now() + interval '30 minutes'), created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE INDEX telegram_pending_actions_user_status_idx ON public.telegram_pending_actions(user_id, status, created_at DESC);
CREATE TABLE public.telegram_webhook_updates (update_id bigint PRIMARY KEY, processed_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.telegram_link_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.telegram_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.telegram_pending_actions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.telegram_webhook_updates ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.telegram_link_codes, public.telegram_accounts, public.telegram_pending_actions, public.telegram_webhook_updates FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.telegram_link_codes, public.telegram_accounts, public.telegram_pending_actions, public.telegram_webhook_updates TO service_role;
CREATE OR REPLACE FUNCTION public.link_telegram_account(p_code_hash text, p_telegram_user_id bigint, p_chat_id bigint, p_username text DEFAULT NULL, p_first_name text DEFAULT NULL, p_last_name text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $function$ DECLARE v_user_id uuid; v_existing_user uuid; BEGIN IF p_code_hash IS NULL OR p_code_hash !~ '^[0-9a-f]{64}$' OR p_telegram_user_id IS NULL OR p_chat_id IS NULL THEN RETURN false; END IF; SELECT user_id INTO v_user_id FROM public.telegram_link_codes WHERE code_hash = p_code_hash AND used_at IS NULL AND expires_at > pg_catalog.now() FOR UPDATE; IF v_user_id IS NULL THEN RETURN false; END IF; SELECT user_id INTO v_existing_user FROM public.telegram_accounts WHERE telegram_user_id = p_telegram_user_id; IF v_existing_user IS NOT NULL AND v_existing_user <> v_user_id THEN RETURN false; END IF; INSERT INTO public.telegram_accounts(user_id,telegram_user_id,chat_id,username,first_name,last_name,linked_at) VALUES(v_user_id,p_telegram_user_id,p_chat_id,nullif(left(p_username,64),''),nullif(left(p_first_name,128),''),nullif(left(p_last_name,128),''),pg_catalog.now()) ON CONFLICT(user_id) DO UPDATE SET telegram_user_id=excluded.telegram_user_id,chat_id=excluded.chat_id,username=excluded.username,first_name=excluded.first_name,last_name=excluded.last_name,linked_at=pg_catalog.now(); UPDATE public.telegram_link_codes SET used_at=pg_catalog.now() WHERE code_hash=p_code_hash; DELETE FROM public.telegram_link_codes WHERE user_id=v_user_id AND used_at IS NULL; RETURN true; EXCEPTION WHEN unique_violation THEN RETURN false; END; $function$;
CREATE OR REPLACE FUNCTION public.resolve_telegram_pending_action(p_pending_id uuid, p_telegram_user_id bigint, p_chat_id bigint, p_decision text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $function$ DECLARE v_pending public.telegram_pending_actions%rowtype; v_account_user uuid; v_save public.life_rpg_saves%rowtype; v_entry jsonb; v_new_entries jsonb := '[]'::jsonb; v_count integer := 0; v_now_ms bigint; BEGIN IF p_decision IS NULL OR p_decision NOT IN ('confirm','reject') THEN RETURN jsonb_build_object('ok',false,'reason','invalid_decision'); END IF; SELECT user_id INTO v_account_user FROM public.telegram_accounts WHERE telegram_user_id=p_telegram_user_id AND chat_id=p_chat_id; IF v_account_user IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','not_linked'); END IF; SELECT * INTO v_pending FROM public.telegram_pending_actions WHERE id=p_pending_id AND user_id=v_account_user AND telegram_user_id=p_telegram_user_id AND chat_id=p_chat_id FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','not_found'); END IF; IF v_pending.status <> 'pending' THEN RETURN jsonb_build_object('ok',false,'reason','already_resolved'); END IF; IF v_pending.expires_at <= pg_catalog.now() THEN UPDATE public.telegram_pending_actions SET status='expired',resolved_at=pg_catalog.now() WHERE id=p_pending_id; RETURN jsonb_build_object('ok',false,'reason','expired'); END IF; IF p_decision='reject' THEN UPDATE public.telegram_pending_actions SET status='rejected',resolved_at=pg_catalog.now() WHERE id=p_pending_id; RETURN jsonb_build_object('ok',true,'status','rejected','count',0); END IF; SELECT * INTO v_save FROM public.life_rpg_saves WHERE user_id=v_account_user FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','save_not_found'); END IF; v_now_ms := (extract(epoch from pg_catalog.now())*1000)::bigint; FOR v_entry IN SELECT value FROM jsonb_array_elements(v_pending.proposal) LOOP v_new_entries := v_new_entries || jsonb_build_array(jsonb_build_object('id',gen_random_uuid()::text,'at',v_now_ms,'type','telegram_activity','title',left(coalesce(v_entry->>'title','Действие'),160),'xp',0,'bonusXp',0,'habit',false,'result',left(coalesce(v_entry->>'description',''),500),'source','telegram','category',left(coalesce(v_entry->>'category','other'),32),'durationMinutes',greatest(0,least(1440,coalesce((v_entry->>'duration_minutes')::integer,0))),'quantity',greatest(0,least(1000000,coalesce((v_entry->>'quantity')::numeric,0))),'unit',left(coalesce(v_entry->>'unit',''),24))); v_count := v_count+1; END LOOP; UPDATE public.life_rpg_saves SET data=jsonb_set(v_save.data,'{activityLog}',(SELECT coalesce(jsonb_agg(item),'[]'::jsonb) FROM (SELECT value AS item FROM jsonb_array_elements(v_new_entries || CASE WHEN jsonb_typeof(v_save.data->'activityLog')='array' THEN v_save.data->'activityLog' ELSE '[]'::jsonb END) WITH ORDINALITY AS e(value,ord) ORDER BY ord LIMIT 300) retained),true),updated_at=pg_catalog.now() WHERE user_id=v_account_user; UPDATE public.telegram_pending_actions SET status='confirmed',resolved_at=pg_catalog.now() WHERE id=p_pending_id; RETURN jsonb_build_object('ok',true,'status','confirmed','count',v_count); END; $function$;
REVOKE ALL ON FUNCTION public.link_telegram_account(text,bigint,bigint,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.link_telegram_account(text,bigint,bigint,text,text,text) TO service_role;
REVOKE ALL ON FUNCTION public.resolve_telegram_pending_action(uuid,bigint,bigint,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_telegram_pending_action(uuid,bigint,bigint,text) TO service_role;
